{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Practolol, a close aryloxypropanolamine analogue with a para-acetamido group and isopropylamino side chain, has absolute oral bioavailability of 90–100% in humans, supporting high F for the similarly polar beta-blocker-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Penbutolol, which shares the tert-butylamino hydroxypropoxy motif, has absolute oral bioavailability of 90% in humans, indicating that the tert-butylamino side chain is compatible with high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Celiprolol, containing both a tert-butylamino side chain and a para-urea substituent like the query, has absolute oral bioavailability of 30–70% in healthy subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tertatolol, another tert-butylamino aryloxypropanolamine, has absolute oral bioavailability of 60% in healthy subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Atenolol, a polar and ionizable aryloxypropanolamine beta-blocker, has absolute oral bioavailability of 50–60%, showing that polar/ionizable beta-blockers can still exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Pafenolol, which has a para-urea-containing side chain, has systemic availability of 27 ± 5% at 25 mg, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence from structurally related beta-blockers, including those with tert-butylamino and para-urea/amide substituents, reports absolute oral bioavailability above 20% (mostly 27–100%). The query's physicochemical liabilities are not sufficient to overturn this consistent experimental pattern; predict high F.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Metabolic stability and first-pass clearance of the query are not experimentally characterized.",
    "Transporter effects and dose-dependent bioavailability, seen in some analogues such as celiprolol and pafenolol, are unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

